-- ############################################
-- 八、SQL 模板（SQL模板库表单）5 条
-- ############################################
INSERT INTO "HBGRCZHEZ"."TBL_SQL_TEMPLATE" (TEMPLATE_ID, TEMPLATE_CODE, TEMPLATE_NAME, TEMPLATE_TYPE, BUSINESS_SCENARIO, SQL_CONTENT, DESCRIPTION, COMPLEXITY_LEVEL, IS_SYSTEM, CREATE_USER, CREATE_TIME) VALUES ('95552301', 'TPL-ZZ-001', '资产负债率监控模板', 'FINANCE', '财务风险监控', 'SELECT ORG_NAME, ROUND(TOTAL_LIAB / NULLIF(TOTAL_ASSET,0) * 100, 2) AS ASSET_LIAB_RATIO FROM FIN_BALANCE WHERE STAT_PERIOD = #period#', '按期间计算各公司资产负债率', 'LOW', 'N', 'xg', '2026-09-23 17:30:00');
INSERT INTO "HBGRCZHEZ"."TBL_SQL_TEMPLATE" (TEMPLATE_ID, TEMPLATE_CODE, TEMPLATE_NAME, TEMPLATE_TYPE, BUSINESS_SCENARIO, SQL_CONTENT, DESCRIPTION, COMPLEXITY_LEVEL, IS_SYSTEM, CREATE_USER, CREATE_TIME) VALUES ('95552302', 'TPL-CG-001', '采购集中度监控模板', 'PROCUREMENT', '采购风险监控', 'SELECT SUPPLIER_NAME, SUM(AMOUNT) AS TOTAL_AMOUNT FROM PURCHASE_ORDER GROUP BY SUPPLIER_NAME ORDER BY TOTAL_AMOUNT DESC', '统计供应商采购金额集中度', 'MEDIUM', 'N', 'xg', '2026-09-23 17:30:01');
INSERT INTO "HBGRCZHEZ"."TBL_SQL_TEMPLATE" (TEMPLATE_ID, TEMPLATE_CODE, TEMPLATE_NAME, TEMPLATE_TYPE, BUSINESS_SCENARIO, SQL_CONTENT, DESCRIPTION, COMPLEXITY_LEVEL, IS_SYSTEM, CREATE_USER, CREATE_TIME) VALUES ('95552303', 'TPL-HT-001', '合同履约逾期监控模板', 'PROCUREMENT', '合同风险监控', 'SELECT CONTRACT_CODE, PLAN_END_DATE FROM CONTRACT WHERE PLAN_END_DATE < #current_date# AND STATUS = 2', '筛选已逾期未履约合同', 'LOW', 'N', 'xg', '2026-09-23 17:30:02');
INSERT INTO "HBGRCZHEZ"."TBL_SQL_TEMPLATE" (TEMPLATE_ID, TEMPLATE_CODE, TEMPLATE_NAME, TEMPLATE_TYPE, BUSINESS_SCENARIO, SQL_CONTENT, DESCRIPTION, COMPLEXITY_LEVEL, IS_SYSTEM, CREATE_USER, CREATE_TIME) VALUES ('95552304', 'TPL-SJ-001', '审计问题整改超期模板', 'AUDIT', '审计整改监控', 'SELECT ISSUE_CODE, DEADLINE FROM AUDIT_ISSUE WHERE DEADLINE < #current_date# AND RECTIFY_STATUS <> 1', '筛选审计整改超期问题', 'MEDIUM', 'N', 'xg', '2026-09-23 17:30:03');
INSERT INTO "HBGRCZHEZ"."TBL_SQL_TEMPLATE" (TEMPLATE_ID, TEMPLATE_CODE, TEMPLATE_NAME, TEMPLATE_TYPE, BUSINESS_SCENARIO, SQL_CONTENT, DESCRIPTION, COMPLEXITY_LEVEL, IS_SYSTEM, CREATE_USER, CREATE_TIME) VALUES ('95552305', 'TPL-CW-002', '大额资金流出监控模板', 'FINANCE', '资金风险监控', 'SELECT PAY_DATE, PAYEE, AMOUNT FROM FUND_FLOW WHERE AMOUNT > #threshold# AND PAY_DATE >= #start_date#', '筛选超过阈值的资金流出记录', 'LOW', 'N', 'xg', '2026-09-23 17:30:04');

