INSERT INTO "HBGRCZHEZ"."TBL_DATA_MODEL" (MODEL_ID, MODEL_CODE, MODEL_NAME, MODEL_TYPE, BUSINESS_MEANING, DATA_SOURCE_ID, SQL_STATEMENT, TEMPLATE_ID, TEMPLATE_TYPE, VERSION, STATUS, IS_ENABLED, CREATE_USER, CREATE_TIME) VALUES ('95552401', 'MDL-2026-001', '资产负债率预警模型', 'RISK', '监控各公司资产负债率超限情况', '95552201', 'SELECT ORG_NAME, ROUND(TOTAL_LIAB / NULLIF(TOTAL_ASSET,0) * 100, 2) AS RATIO FROM FIN_BALANCE WHERE STAT_PERIOD = #period#', '95552301', 'FINANCE', 'V1.0', 'PUBLISHED', 'Y', 'xg', '2026-09-23 17:40:00');
