INSERT INTO "HBGRCZHEZ"."TBL_DATA_MODEL" (MODEL_ID, MODEL_CODE, MODEL_NAME, MODEL_TYPE, BUSINESS_MEANING, DATA_SOURCE_ID, SQL_STATEMENT, TEMPLATE_ID, TEMPLATE_TYPE, VERSION, STATUS, IS_ENABLED, CREATE_USER, CREATE_TIME) VALUES ('95552403', 'MDL-2026-003', '合同履约逾期模型', 'FINANCIAL', '监控合同履约逾期情况', '95552203', 'SELECT CONTRACT_CODE, PLAN_END_DATE FROM CONTRACT WHERE PLAN_END_DATE < #current_date# AND STATUS = 2', '95552303', 'PROCUREMENT', 'V1.0', 'PUBLISHED', 'Y', 'xg', '2026-09-23 17:40:02');
INSERT INTO "HBGRCZHEZ"."TBL_DATA_MODEL" (MODEL_ID, MODEL_CODE, MODEL_NAME, MODEL_TYPE, BUSINESS_MEANING, DATA_SOURCE_ID, SQL_STATEMENT, TEMPLATE_ID, TEMPLATE_TYPE, VERSION, STATUS, IS_ENABLED, CREATE_USER, CREATE_TIME) VALUES ('95552404', 'MDL-2026-004', '审计整改超期模型', 'AUDIT', '监控审计问题整改超期', '95552204', 'SELECT ISSUE_CODE, DEADLINE FROM AUDIT_ISSUE WHERE DEADLINE < #current_date# AND RECTIFY_STATUS <> 1', '95552304', 'AUDIT', 'V1.0', 'PUBLISHED', 'Y', 'xg', '2026-09-23 17:40:03');
INSERT INTO "HBGRCZHEZ"."TBL_DATA_MODEL" (MODEL_ID, MODEL_CODE, MODEL_NAME, MODEL_TYPE, BUSINESS_MEANING, DATA_SOURCE_ID, SQL_STATEMENT, TEMPLATE_ID, TEMPLATE_TYPE, VERSION, STATUS, IS_ENABLED, CREATE_USER, CREATE_TIME) VALUES ('95552405', 'MDL-2026-005', '大额资金流出模型', 'FINANCIAL', '监控大额资金异常流出', '95552205', 'SELECT PAY_DATE, PAYEE, AMOUNT FROM FUND_FLOW WHERE AMOUNT > #threshold#', '95552305', 'FINANCE', 'V1.0', 'PUBLISHED', 'Y', 'xg', '2026-09-23 17:40:04');

