INSERT INTO "HBGRCZHEZ"."TBL_INDICATOR" (INDICATORID, INDICATORCODE, INDICATORNAME, FORMULA, INDICATORDES, MEMO, ORGID, DEPARTMENTINCHARGE, INDICATORSTATUS, AUDITINGSTATUS, CREATEDATE, UNITTYPE, FORMULADES, RUNSTATUS, STAFFID, CONNECTIONSTRINGS, INDICATORDB, FORLUMACHS) VALUES (88140421, 'ZB-2026-001', '大额资金支付占比', 'SELECT SUM(CASE WHEN AMOUNT>500000 THEN 1 ELSE 0 END)/COUNT(1) FROM TBL_PAYMENT WHERE BELONGGROUP=1000', '监测单笔超50万支付笔数占比', '测试数据', 1000, '合规风控部（法务部）', '启用', '已审核', '2026-08-01 09:00:00', '%', '大额支付笔数占总支付笔数比例', 0, 5555, 'jdbc:dm://127.0.0.1:5236/HBGRCZHEZ', 0, 'hashzb0001');
