INSERT INTO "HBGRCZHEZ"."TBL_INDICATOR" (INDICATORID, INDICATORCODE, INDICATORNAME, FORMULA, INDICATORDES, MEMO, ORGID, DEPARTMENTINCHARGE, INDICATORSTATUS, AUDITINGSTATUS, CREATEDATE, UNITTYPE, FORMULADES, RUNSTATUS, STAFFID, CONNECTIONSTRINGS, INDICATORDB, FORLUMACHS) VALUES (88140423, 'ZB-2026-003', '合同归档及时率', 'SELECT ONTIME/CNT FROM V_CONTRACT_ARCHIVE WHERE ORGID=1000', '监测合同按期归档比例', '测试数据', 1000, '合规风控部（法务部）', '启用', '已审核', '2026-08-01 09:02:00', '%', '按期归档合同数占合同总数比例', 0, 5555, 'jdbc:dm://127.0.0.1:5236/HBGRCZHEZ', 0, 'hashzb0003');
