INSERT INTO "HBGRCZHEZ"."TBL_ZSGX_LAW_REGULATION" (ID, TITLE, DOCUMENT_NO, CONTENT, IMPLEMENT_DATE, ISSUE_DATE, ISSUE_YEAR, ISSUE_DEPARTMENT_CODE, ISSUE_DEPARTMENT_NAME, CONTRACT_TYPE_CODE, CONTRACT_TYPE_NAME, EFFECTIVENESS_DIC_CODE, EFFECTIVENESS_DIC_NAME, TIMELINESS_DIC_CODE, TIMELINESS_DIC_NAME, CREATE_COMPANY, CREATE_DEPT, CREATE_BY, CREATE_TIME, UPDATE_TIME, UPDATE_BY, DELETED) VALUES ('88150012', '中华人民共和国证券法', '主席令第三十七号', '为了规范证券发行和交易行为，保护投资者的合法权益，维护社会经济秩序和社会公共利益，促进社会主义市场经济的发展，制定本法。', '2020-03-01', '2019-12-28', '2019', '100', '全国人民代表大会常务委员会', 'QY', '企业常用', 'FL', '法律', 'XX', '现行有效', '1000', '839006', '5555', '2026-07-02 09:01:00', '2026-07-02 09:01:00', '5555', 0);
